package com.vibeguard.samples.payments;
import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Positive; import java.util.Map; import java.util.UUID; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
/** Simulates a configured third-party payment provider locally. */ @RestController @RequestMapping("/api/payments") public class PaymentController { private final Map<String,Payment> payments=new ConcurrentHashMap<>(); @Value("${PAYMENT_PROVIDER_API_KEY:}") private String providerApiKey;
 @PostMapping("/charges") public ResponseEntity<Payment> charge(@Valid @RequestBody Charge input){if(providerApiKey.isBlank())return ResponseEntity.status(503).build(); String id=UUID.randomUUID().toString(); Payment payment=new Payment(id,input.amount(),input.currency(),"SUCCEEDED");payments.put(id,payment);return ResponseEntity.ok(payment);} @GetMapping("/{id}") public ResponseEntity<Payment> get(@PathVariable String id){Payment payment=payments.get(id);return payment==null?ResponseEntity.notFound().build():ResponseEntity.ok(payment);} record Charge(@Positive long amount,@NotBlank String currency){} record Payment(String id,long amount,String currency,String status){} }
